SELECT * FROM( SELECT *,@rownum:=@rownum+1 as rownum FROM( SELECT shop_id ,staff_id ,staff_name ,(select shop_name from shop where shop_id=staff.shop_id) shop_name ,position FROM staff
shop_id = #{shopId}
and ( staff_name like CONCAT('%', #{staffName}, '%') )
) A,(select @rownum:=0) R ORDER BY shop_name,staff_name ) B
rownum > (#{pageSize}*(#{currentPage}-1)) and (#{pageSize}*(#{currentPage})) >= rownum

